package de.corporate.lc.swift; import de.corporate.lc.lc.domain.Amendment; import org.springframework.stereotype.Component; import java.math.*; import java.time.*; import java.time.format.*; import java.util.*; import java.util.regex.*;
@Component public class Mt707Parser {private static final Pattern FIELD=Pattern.compile("(?m)^:(\\d{2}[A-Z]?):(.*?)(?=^:\\d{2}[A-Z]?:|\\z)",Pattern.DOTALL); public record Parsed(String lcReference,Amendment amendment){} public Parsed parse(String raw){Map<String,String> f=new LinkedHashMap<>();Matcher m=FIELD.matcher(raw.strip());while(m.find())f.put(m.group(1),m.group(2).trim());Amendment a=new Amendment();a.setRawMessage(raw);a.setAmendmentNumber(f.get("26E"));if(f.containsKey("30"))a.setAmendmentDate(date(f.get("30")));if(f.containsKey("31E")){String x=f.get("31E");a.setNewExpiryDate(date(x.substring(0,6)));if(x.length()>6)a.setNewExpiryPlace(x.substring(6).trim());}if(f.containsKey("44C"))a.setNewLatestShipmentDate(date(f.get("44C").substring(0,6)));if(f.containsKey("32B"))a.setAmountIncrease(amount(f.get("32B")));if(f.containsKey("33B"))a.setAmountDecrease(amount(f.get("33B")));a.setChangedDocuments(f.get("46B"));return new Parsed(req(f,"20"),a);} private BigDecimal amount(String x){x=x.replace("\n","").trim();return new BigDecimal(x.substring(3).replace(".","").replace(',','.'));}private LocalDate date(String s){return LocalDate.parse(s.trim(),DateTimeFormatter.ofPattern("yyMMdd"));}private String req(Map<String,String> f,String k){if(!f.containsKey(k))throw new IllegalArgumentException("MT707 field :"+k+": is required");return f.get(k);}}
